export class LineDecoder{
 constructor(){this.characters=[];this.closed=false;}
 push(chunk){
  if(this.closed)throw Object.assign(new Error('closed'),{code:'LINE_DECODER_CLOSED'});
  const result=[];
  for(const char of chunk){if(char==='\n'){if(this.characters.at(-1)==='\r')this.characters.pop();result.push(this.characters.join(''));this.characters=[];}else this.characters.push(char);}
  return result;
 }
 finish(){if(this.closed)return [];this.closed=true;const final=this.characters.join('');this.characters=[];return final===''?[]:[final];}
}
export function splitLines(text){const parser=new LineDecoder();const lines=parser.push(text);return lines.concat(parser.finish());}

